	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
)

func main() {
	repo, err := git.PlainOpen(".")
	if err != nil {
		panic(err)
	}

	tagName := "@name/subname@v1.0.1"
	_, err = repo.ResolveRevision(plumbing.Revision(tagName))
	if err != nil {
		panic(err)
	}
}
```

```
$ git tag                                                                                                     
@name/subname@v1.0.1
$ git rev-list -n 1 @name/subname@v1.0.1
c93521b3316ee00c2d8f190b1420ed0adde79f6c          
$ ./main
panic: Revision invalid : reference must be defined once at the beginning                    
```

Workaround

As a workaround, I resolve the tag by reference hash instead of its name.

```go
package main

import (
	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
)

func main() {
	repo, err := git.PlainOpen(".")
	if err != nil {
		panic(err)
	}

	tagName := "@name/subname@v1.0.1"
	reference, err := repo.Tag(tagName)
	if err != nil {
		panic(err)
	}

	_, err = repo.ResolveRevision(plumbing.Revision(reference.Hash().String()))
	if err != nil {
		panic(err)
	}
}
