def test_schema_nested_assignment_is_validated():
    """validate_assignment still validates (and rejects) nested values."""

    class Bar(Schema):
        b: Optional[str] = None
        model_config = {"validate_assignment": True}

    class Foo(Schema):
        n: int = 0
        bar: Optional[Bar] = None
